"""C046 r1: general size lower bound k+5 for separators of consecutive graded FairBots F_k = []^k p, F_{k+1}.
Language L: atoms p (opponent's move vs me), q (opponent's move vs DefectBot); F,~,&,|,[]; guarded; size = AST
nodes; height semantics; game wiring as in K38 (O's p = F_j's move vs O, O's q = F_j's DefectBot trace h<j).
Part 1 (Lean 4 core, SHA-pinned; includes the K58 depth development verbatim):
 negfree_same -- a guarded opponent without negation gets the same outcome against F_j and F_j' (all j, j');
   in threshold models it evaluates to a threshold whose infiniteness does not depend on finite thresholds.
 nobin_same -- a guarded opponent without & / | gets the same outcome against F_j and F_j' (j, j' >= 1);
   its traces stay (co-)thresholds and their class (infinite / zero / positive) is preserved.
 size_bound -- hence for every k >= 1 every guarded separator of F_k, F_{k+1} contains a negation and a binary
   connective and has modal depth >= k+1 (K58), so >= k+1 boxes and >= 4 other nodes: size >= k+5.
 sk_size -- S_k = [](~q | []^k F) has size k+5, so the bound is attained (K49). No sorryAx; 4 mutations rejected.
Part 2 (independent literal evaluator): every guarded formula of size <= 8 that is negation-free or binary-free gets
 the same outcome against F_1..F_5; at size <= 9 every F_k/F_{k+1} separator (k <= 4) has a negation and a binary node.
Scope: lower bound only for opponents in L with atoms p,q; the q-free minimum k+6 (K56) is not proved here.
"""
LEAN = "set_option linter.unusedVariables false\n\ninductive Fm where\n  | bot | pa | qa | neg (a : Fm) | cj (a b : Fm) | dj (a b : Fm) | box (a : Fm)\nopen Fm\n\ndef md : Fm → Nat\n  | bot => 0 | pa => 0 | qa => 0\n  | neg a => md a\n  | cj a b => max (md a) (md b)\n  | dj a b => max (md a) (md b)\n  | box a => md a + 1\n\ndef size : Fm → Nat\n  | bot => 1 | pa => 1 | qa => 1\n  | neg a => size a + 1\n  | cj a b => size a + size b + 1\n  | dj a b => size a + size b + 1\n  | box a => size a + 1\n\ndef ev (P Q : Nat → Prop) : Fm → Nat → Prop\n  | bot, _ => False\n  | pa, h => P h\n  | qa, h => Q h\n  | neg a, h => ¬ ev P Q a h\n  | cj a b, h => ev P Q a h ∧ ev P Q b h\n  | dj a b, h => ev P Q a h ∨ ev P Q b h\n  | box a, h => ∀ g, g < h → ev P Q a g\n\ndef Guarded : Fm → Prop\n  | bot => True | pa => False | qa => False\n  | neg a => Guarded a\n  | cj a b => Guarded a ∧ Guarded b\n  | dj a b => Guarded a ∧ Guarded b\n  | box _ => True\n\ntheorem md_lt_size (a : Fm) : md a + 1 ≤ size a := by\n  induction a <;> simp only [md, size] <;> omega\n\n/-- causality: agreement up to h fixes truth at h -/\ntheorem upto (P Q P' Q' : Nat → Prop) : ∀ (a : Fm) (h : Nat),\n    (∀ g, g ≤ h → ((P g ↔ P' g) ∧ (Q g ↔ Q' g))) → (ev P Q a h ↔ ev P' Q' a h) := by\n  intro a\n  induction a with\n  | bot => intro h _; simp [ev]\n  | pa => intro h H; exact (H h (Nat.le_refl _)).1\n  | qa => intro h H; exact (H h (Nat.le_refl _)).2\n  | neg a ih => intro h H; simp only [ev]; rw [ih h H]\n  | cj a b iha ihb => intro h H; simp only [ev]; rw [iha h H, ihb h H]\n  | dj a b iha ihb => intro h H; simp only [ev]; rw [iha h H, ihb h H]\n  | box a ih =>\n    intro h H; simp only [ev]\n    constructor\n    · intro k g hg; exact (ih g (fun x hx => H x (by omega))).1 (k g hg)\n    · intro k g hg; exact (ih g (fun x hx => H x (by omega))).2 (k g hg)\n\n/-- guarded causality: agreement strictly below h fixes truth at h -/\ntheorem below (P Q P' Q' : Nat → Prop) : ∀ (a : Fm) (h : Nat), Guarded a →\n    (∀ g, g < h → ((P g ↔ P' g) ∧ (Q g ↔ Q' g))) → (ev P Q a h ↔ ev P' Q' a h) := by\n  intro a\n  induction a with\n  | bot => intro h _ _; simp [ev]\n  | pa => intro h hg; exact hg.elim\n  | qa => intro h hg; exact hg.elim\n  | neg a ih => intro h hg H; simp only [ev]; rw [ih h hg H]\n  | cj a b iha ihb => intro h hg H; simp only [ev]; rw [iha h hg.1 H, ihb h hg.2 H]\n  | dj a b iha ihb => intro h hg H; simp only [ev]; rw [iha h hg.1 H, ihb h hg.2 H]\n  | box a ih =>\n    intro h _ H; simp only [ev]\n    constructor\n    · intro k g hg; exact (upto P Q P' Q' a g (fun x hx => H x (by omega))).1 (k g hg)\n    · intro k g hg; exact (upto P Q P' Q' a g (fun x hx => H x (by omega))).2 (k g hg)\n\n/-! Threshold models: p true below Pt, q true below Qt (Qt ≤ Pt). -/\ndef T (n : Nat) : Nat → Prop := fun g => g < n\n\n/-- clipped block counts of the prefix [0,a): q-block, p-only block, empty block -/\ndef Cnt (d Pt Qt Pt' Qt' a b : Nat) : Prop :=\n  min (min a Qt) d = min (min b Qt') d ∧\n  min (min (a - Qt) (Pt - Qt)) d = min (min (b - Qt') (Pt' - Qt')) d ∧\n  min (a - Pt) d = min (b - Pt') d\n\ndef Lab (Pt Qt Pt' Qt' a b : Nat) : Prop := (a < Pt ↔ b < Pt') ∧ (a < Qt ↔ b < Qt')\n\ntheorem cnt_symm {d Pt Qt Pt' Qt' a b : Nat} : Cnt d Pt Qt Pt' Qt' a b → Cnt d Pt' Qt' Pt Qt b a := by\n  unfold Cnt; omega\n\ntheorem forth {d Pt Qt Pt' Qt' a b a' : Nat} (hQ : Qt ≤ Pt) (hQ' : Qt' ≤ Pt')\n    (H : Cnt (d+1) Pt Qt Pt' Qt' a b) (ha : a' < a) :\n    ∃ b', b' < b ∧ Cnt d Pt Qt Pt' Qt' a' b' ∧ Lab Pt Qt Pt' Qt' a' b' := by\n  obtain ⟨H0, H1, H2⟩ := H\n  unfold Cnt Lab\n  by_cases h0 : a' < Qt\n  · have hb : min a' d < min b Qt' := by clear H1 H2; omega\n    clear H0 H1 H2\n    exact ⟨min a' d, by omega, ⟨by omega, by omega, by omega⟩, by omega⟩\n  · by_cases h1 : a' < Pt\n    · have hb : min (a' - Qt) d < min (b - Qt') (Pt' - Qt') := by clear H0 H2; omega\n      have e0 : min Qt d = min Qt' d := by clear H1 H2; omega\n      clear H0 H1 H2\n      exact ⟨Qt' + min (a' - Qt) d, by omega, ⟨by omega, by omega, by omega⟩, by omega⟩\n    · have hb : min (a' - Pt) d < b - Pt' := by clear H0 H1; omega\n      have e0 : min Qt d = min Qt' d := by clear H1 H2; omega\n      have e1 : min (Pt - Qt) d = min (Pt' - Qt') d := by clear H0 H2; omega\n      clear H0 H1 H2\n      exact ⟨Pt' + min (a' - Pt) d, by omega, ⟨by omega, by omega, by omega⟩, by omega⟩\n\n/-- depth-d formulas cannot tell related positions of two threshold models apart -/\ntheorem ev_rel {Pt Qt Pt' Qt' : Nat} (hQ : Qt ≤ Pt) (hQ' : Qt' ≤ Pt') : ∀ (φ : Fm) (d a b : Nat),\n    md φ ≤ d → Cnt d Pt Qt Pt' Qt' a b → Lab Pt Qt Pt' Qt' a b →\n    (ev (T Pt) (T Qt) φ a ↔ ev (T Pt') (T Qt') φ b) := by\n  intro φ\n  induction φ with\n  | bot => intro d a b _ _ _; simp [ev]\n  | pa => intro d a b _ _ L; simp only [ev, T]; exact L.1\n  | qa => intro d a b _ _ L; simp only [ev, T]; exact L.2\n  | neg a ih => intro d x y hd C L; simp only [ev, md] at *; rw [ih d x y hd C L]\n  | cj a b iha ihb =>\n    intro d x y hd C L; simp only [ev, md] at *\n    rw [iha d x y (by omega) C L, ihb d x y (by omega) C L]\n  | dj a b iha ihb =>\n    intro d x y hd C L; simp only [ev, md] at *\n    rw [iha d x y (by omega) C L, ihb d x y (by omega) C L]\n  | box a ih =>\n    intro d x y hd C L; simp only [ev, md] at *\n    obtain ⟨d', rfl⟩ : ∃ d', d = d' + 1 := ⟨d - 1, by omega⟩\n    constructor\n    · intro k y' hy'\n      obtain ⟨x', hx', C', L'⟩ := forth hQ' hQ (cnt_symm C) hy'\n      exact (ih d' x' y' (by omega) (cnt_symm C') (by unfold Lab at *; omega)).1 (k x' hx')\n    · intro k x' hx'\n      obtain ⟨y', hy', C', L'⟩ := forth hQ hQ' C hx'\n      exact (ih d' x' y' (by omega) C' L').2 (k y' hy')\n\n/-- for guarded formulas the own label is irrelevant -/\ntheorem ev_guarded {Pt Qt Pt' Qt' : Nat} (hQ : Qt ≤ Pt) (hQ' : Qt' ≤ Pt') : ∀ (φ : Fm) (d a b : Nat),\n    Guarded φ → md φ ≤ d → Cnt d Pt Qt Pt' Qt' a b →\n    (ev (T Pt) (T Qt) φ a ↔ ev (T Pt') (T Qt') φ b) := by\n  intro φ\n  induction φ with\n  | bot => intro d a b _ _ _; simp [ev]\n  | pa => intro d a b hg; exact hg.elim\n  | qa => intro d a b hg; exact hg.elim\n  | neg a ih => intro d x y hg hd C; simp only [ev, md, Guarded] at *; rw [ih d x y hg hd C]\n  | cj a b iha ihb =>\n    intro d x y hg hd C; simp only [ev, md, Guarded] at *\n    rw [iha d x y hg.1 (by omega) C, ihb d x y hg.2 (by omega) C]\n  | dj a b iha ihb =>\n    intro d x y hg hd C; simp only [ev, md, Guarded] at *\n    rw [iha d x y hg.1 (by omega) C, ihb d x y hg.2 (by omega) C]\n  | box a _ =>\n    intro d x y _ hd C; simp only [ev, md] at *\n    obtain ⟨d', rfl⟩ : ∃ d', d = d' + 1 := ⟨d - 1, by omega⟩\n    constructor\n    · intro k y' hy'\n      obtain ⟨x', hx', C', L'⟩ := forth hQ' hQ (cnt_symm C) hy'\n      exact (ev_rel hQ hQ' a d' x' y' (by omega) (cnt_symm C') (by unfold Lab at *; omega)).1 (k x' hx')\n    · intro k x' hx'\n      obtain ⟨y', hy', C', L'⟩ := forth hQ hQ' C hx'\n      exact (ev_rel hQ hQ' a d' x' y' (by omega) C' L').2 (k y' hy')\n\n/-! Games of an opponent O against F_j = box^j p (K38 wiring):\n O's p = F_j's move, O's q = F_j's DefectBot trace (h < j); F_j's move needs O's moves at all g ≤ h - j. -/\ndef GameRec (O : Fm) (j : Nat) (o f : Nat → Prop) : Prop :=\n  ∀ h, (o h ↔ ev f (T j) O h) ∧ (f h ↔ ∀ g, g + j ≤ h → o g)\n\n/-- O against an all-cooperating partner -/\ndef A (O : Fm) (j x : Nat) : Prop := ev (fun _ => True) (T j) O x\n\ntheorem prefix_agree {O : Fm} {j : Nat} {o f : Nat → Prop} (hg : Guarded O) (G : GameRec O j o f)\n    (h : Nat) (hA : ∀ x, x < h → A O j x) : ∀ x, x ≤ h → (o x ↔ A O j x) := by\n  have main : ∀ n, ∀ x, x < n → x ≤ h → (o x ↔ A O j x) := by\n    intro n\n    induction n with\n    | zero => intro x hx; omega\n    | succ n ih =>\n      intro x hxn hx\n      rw [(G x).1]\n      apply below _ _ _ _ O x hg\n      intro g hg'\n      refine ⟨?_, Iff.rfl⟩\n      rw [(G g).2]\n      constructor\n      · intro _; trivial\n      · intro _ y hy\n        exact (ih y (by omega) (by omega)).2 (hA y (by omega))\n  exact fun x hx => main (x+1) x (by omega) hx\n\ntheorem all_coop {O : Fm} {j : Nat} {o f : Nat → Prop} (hg : Guarded O) (G : GameRec O j o f)\n    (hA : ∀ x, A O j x) : ∀ h, o h ∧ f h := by\n  have ho : ∀ h, o h := fun h => (prefix_agree hg G h (fun x _ => hA x) h (Nat.le_refl _)).2 (hA h)\n  exact fun h => ⟨ho h, (G h).2.2 (fun g _ => ho g)⟩\n\ntheorem tail_form {O : Fm} {j : Nat} {o f : Nat → Prop} (hg : Guarded O) (G : GameRec O j o f)\n    (g0 : Nat) (h0 : ¬ A O j g0) (hlt : ∀ x, x < g0 → A O j x) :\n    (∀ h, (f h ↔ h < g0 + j)) ∧ (∀ h, (o h ↔ ev (T (g0 + j)) (T j) O h)) := by\n  have pa := prefix_agree hg G g0 hlt\n  have hf : ∀ h, (f h ↔ h < g0 + j) := by\n    intro h\n    rw [(G h).2]\n    constructor\n    · intro k\n      apply Classical.byContradiction\n      intro hn\n      exact h0 ((pa g0 (Nat.le_refl _)).1 (k g0 (by omega)))\n    · intro hh y hy\n      exact (pa y (by omega)).2 (hlt y (by omega))\n  refine ⟨hf, fun h => ?_⟩\n  rw [(G h).1]\n  exact upto _ _ _ _ O h (fun g _ => ⟨hf g, Iff.rfl⟩)\n\ntheorem A_model {O : Fm} (hg : Guarded O) (j x Pt : Nat) (hx : x < Pt) :\n    (A O j x ↔ ev (T Pt) (T j) O x) :=\n  below _ _ _ _ O x hg (fun g hg' => ⟨⟨fun _ => show g < Pt by omega, fun _ => trivial⟩, Iff.rfl⟩)\n\ntheorem corr_low {O : Fm} {k : Nat} (hg : Guarded O) (hd : md O ≤ k) (x : Nat) (hx : x ≤ k) :\n    (A O k x ↔ A O (k+1) x) := by\n  rw [A_model hg k x (x+k+2) (by omega), A_model hg (k+1) x (x+k+2) (by omega)]\n  exact ev_guarded (by omega) (by omega) O k x x hg hd (by unfold Cnt; omega)\n\ntheorem corr_high {O : Fm} {k : Nat} (hg : Guarded O) (hd : md O ≤ k) (x : Nat) (hx : k + 1 ≤ x) :\n    (A O k (x - 1) ↔ A O (k+1) x) := by\n  rw [A_model hg k (x-1) (x+k+2) (by omega), A_model hg (k+1) x (x+k+2) (by omega)]\n  exact ev_guarded (by omega) (by omega) O k (x-1) x hg hd (by unfold Cnt; omega)\n\ntheorem least {R : Nat → Prop} (n : Nat) (hn : ¬ R n) : ∃ g, ¬ R g ∧ ∀ x, x < g → R x := by\n  induction n using Nat.strongRecOn with\n  | _ n ih =>\n    by_cases hall : ∀ x, x < n → R x\n    · exact ⟨n, hn, hall⟩\n    · have : ∃ x, x < n ∧ ¬ R x := Classical.byContradiction (fun hc =>\n        hall (fun x hx => Classical.byContradiction (fun hr => hc ⟨x, hx, hr⟩)))\n      obtain ⟨x, hx, hr⟩ := this\n      exact ih x hx hr\n\n/-- MAIN: an opponent of modal depth ≤ k gets the same eventual outcome against F_k and F_{k+1}\n (both all-cooperate, or from some height on its moves coincide and both FairBots defect). -/\ntheorem same_outcome (O : Fm) (k : Nat) (hg : Guarded O) (hd : md O ≤ k)\n    (o f o' f' : Nat → Prop) (G : GameRec O k o f) (G' : GameRec O (k+1) o' f') :\n    ((∀ h, o h ∧ f h) ∧ (∀ h, o' h ∧ f' h)) ∨\n    ∃ H, ∀ h, H ≤ h → ((o h ↔ o' h) ∧ ¬ f h ∧ ¬ f' h) := by\n  classical\n  by_cases hall : ∀ x, A O k x\n  · left\n    refine ⟨all_coop hg G hall, all_coop hg G' ?_⟩\n    intro x\n    by_cases hx : x ≤ k\n    · exact (corr_low hg hd x hx).1 (hall x)\n    · exact (corr_high hg hd x (by omega)).1 (hall (x-1))\n  · right\n    have ex : ∃ x, ¬ A O k x := Classical.byContradiction (fun hn => hall (fun x => Classical.byContradiction (fun hx => hn ⟨x, hx⟩)))\n    have ex' : ∃ x, ¬ A O (k+1) x := by\n      apply Classical.byContradiction\n      intro hn\n      apply hall\n      intro x\n      have hx1 : A O (k+1) (x+1) := Classical.byContradiction (fun hx => hn ⟨x+1, hx⟩)\n      have hx0 : A O (k+1) x := Classical.byContradiction (fun hx => hn ⟨x, hx⟩)\n      by_cases hxk : x ≤ k\n      · exact (corr_low hg hd x hxk).2 hx0\n      · have := (corr_high hg hd (x+1) (by omega)).2 hx1\n        simpa using this\n    obtain ⟨x0, hx0⟩ := ex\n    obtain ⟨x1, hx1⟩ := ex'\n    obtain ⟨g0, s0, m0⟩ := least x0 hx0\n    obtain ⟨g1, s1, m1⟩ := least x1 hx1\n    have key : min g0 k = min g1 k := by\n      by_cases c0 : g0 ≤ k\n      · have n1 : ¬ A O (k+1) g0 := fun h => s0 ((corr_low hg hd g0 c0).2 h)\n        have u1 : g1 ≤ g0 := Classical.byContradiction (fun hc => n1 (m1 g0 (by omega)))\n        have u2 : g0 ≤ g1 := Classical.byContradiction (fun hc =>\n          s1 ((corr_low hg hd g1 (by omega)).1 (m0 g1 (by omega))))\n        omega\n      · by_cases c1 : g1 ≤ k\n        · exact absurd ((corr_low hg hd g1 c1).1 (m0 g1 (by omega))) s1\n        · omega\n    obtain ⟨hf, ho⟩ := tail_form hg G g0 s0 m0\n    obtain ⟨hf', ho'⟩ := tail_form hg G' g1 s1 m1\n    refine ⟨g0 + g1 + 3 * k + 2, fun h hh => ⟨?_, ?_, ?_⟩⟩\n    · rw [ho h, ho' h]\n      exact ev_guarded (by omega) (by omega) O k h h hg hd (by unfold Cnt; omega)\n    · rw [hf h]; omega\n    · rw [hf' h]; omega\n\n/-- corollary: every guarded separator of F_k and F_{k+1} has modal depth ≥ k+1, hence size ≥ k+2 -/\ntheorem separator_bound (O : Fm) (k : Nat) (hg : Guarded O)\n    (o f o' f' : Nat → Prop) (G : GameRec O k o f) (G' : GameRec O (k+1) o' f')\n    (hsep : ¬ (((∀ h, o h ∧ f h) ∧ (∀ h, o' h ∧ f' h)) ∨\n      ∃ H, ∀ h, H ≤ h → ((o h ↔ o' h) ∧ ¬ f h ∧ ¬ f' h))) :\n    k + 1 ≤ md O ∧ k + 2 ≤ size O := by\n  have : k + 1 ≤ md O := by\n    apply Classical.byContradiction\n    intro hn\n    exact hsep (same_outcome O k hg (by omega) o f o' f' G G')\n  have := md_lt_size O\n  omega\n\ndef boxes : Nat → Fm → Fm\n  | 0, a => a\n  | n+1, a => box (boxes n a)\n\ntheorem md_boxes (n : Nat) : md (boxes n bot) = n := by\n  induction n with\n  | zero => rfl\n  | succ n ih => simp [boxes, md, ih]\n\n/-- tightness: K49's S_k = box(~q | box^k F) has depth exactly k+1 -/\ntheorem sk_depth (k : Nat) : md (box (dj (neg qa) (boxes k bot))) = k + 1 := by\n  simp [md, md_boxes]\n\n\n/-! ## Shape lower bound: separators of graded FairBots need a negation and a binary connective -/\n\n/-- outcome equality as in same_outcome -/\ndef SameOut (o f o' f' : Nat → Prop) : Prop :=\n  ((∀ h, o h ∧ f h) ∧ (∀ h, o' h ∧ f' h)) ∨ ∃ H, ∀ h, H ≤ h → ((o h ↔ o' h) ∧ ¬ f h ∧ ¬ f' h)\n\n/-- thresholds with infinity: none = always true -/\ndef TT : Option Nat → Nat → Prop\n  | none, _ => True\n  | some n, h => h < n\n\ntheorem evT (a b : Nat) (O : Fm) (h : Nat) :\n    (ev (T a) (T b) O h ↔ ev (TT (some a)) (TT (some b)) O h) :=\n  upto _ _ _ _ O h (fun g _ => ⟨Iff.rfl, Iff.rfl⟩)\n\ntheorem evA (b : Nat) (O : Fm) (h : Nat) :\n    (ev (fun _ => True) (T b) O h ↔ ev (TT none) (TT (some b)) O h) :=\n  upto _ _ _ _ O h (fun g _ => ⟨Iff.rfl, Iff.rfl⟩)\n\ndef negFree : Fm → Bool\n  | bot => true | pa => true | qa => true\n  | neg _ => false\n  | cj a b => negFree a && negFree b\n  | dj a b => negFree a && negFree b\n  | box a => negFree a\n\ndef noBin : Fm → Bool\n  | bot => true | pa => true | qa => true\n  | neg a => noBin a\n  | cj _ _ => false\n  | dj _ _ => false\n  | box a => noBin a\n\ndef omin : Option Nat → Option Nat → Option Nat\n  | none, y => y\n  | some a, none => some a\n  | some a, some b => some (min a b)\ndef omax : Option Nat → Option Nat → Option Nat\n  | none, _ => none\n  | some _, none => none\n  | some a, some b => some (max a b)\ndef osucc : Option Nat → Option Nat\n  | none => none\n  | some a => some (a + 1)\n\n/-- threshold value of a negation-free formula in a threshold model -/\ndef val (P Q : Option Nat) : Fm → Option Nat\n  | bot => some 0 | pa => P | qa => Q\n  | neg _ => none\n  | cj a b => omin (val P Q a) (val P Q b)\n  | dj a b => omax (val P Q a) (val P Q b)\n  | box a => osucc (val P Q a)\n\ntheorem tt_box (v : Option Nat) (h : Nat) : ((∀ g, g < h → TT v g) ↔ TT (osucc v) h) := by\n  cases v with\n  | none => simp [TT, osucc]\n  | some n =>\n    simp only [TT, osucc]\n    constructor\n    · intro H; apply Classical.byContradiction; intro hn; have := H n (by omega); omega\n    · intro hh g hg; omega\n\ntheorem tt_and (x y : Option Nat) (h : Nat) : ((TT x h ∧ TT y h) ↔ TT (omin x y) h) := by\n  cases x <;> cases y <;> simp [TT, omin] <;> omega\n\ntheorem tt_or (x y : Option Nat) (h : Nat) : ((TT x h ∨ TT y h) ↔ TT (omax x y) h) := by\n  cases x <;> cases y <;> simp [TT, omax] <;> omega\n\ntheorem val_ev (P Q : Option Nat) : ∀ (a : Fm), negFree a = true → ∀ h,\n    (ev (TT P) (TT Q) a h ↔ TT (val P Q a) h) := by\n  intro a\n  induction a with\n  | bot => intro _ h; simp [ev, val, TT]\n  | pa => intro _ h; simp [ev, val]\n  | qa => intro _ h; simp [ev, val]\n  | neg a ih => intro hn; simp [negFree] at hn\n  | cj a b iha ihb =>\n    intro hn h; simp only [negFree, Bool.and_eq_true] at hn\n    simp only [ev, val]; rw [iha hn.1 h, ihb hn.2 h]; exact tt_and _ _ h\n  | dj a b iha ihb =>\n    intro hn h; simp only [negFree, Bool.and_eq_true] at hn\n    simp only [ev, val]; rw [iha hn.1 h, ihb hn.2 h]; exact tt_or _ _ h\n  | box a ih =>\n    intro hn h; simp only [negFree] at hn\n    simp only [ev, val]\n    rw [← tt_box]\n    exact ⟨fun H g hg => (ih hn g).1 (H g hg), fun H g hg => (ih hn g).2 (H g hg)⟩\n\ntheorem val_none (P Q P' Q' : Option Nat) (hP : P.isNone = P'.isNone) (hQ : Q.isNone = Q'.isNone) :\n    ∀ a, (val P Q a).isNone = (val P' Q' a).isNone := by\n  intro a\n  induction a with\n  | bot => rfl\n  | pa => exact hP\n  | qa => exact hQ\n  | neg a _ => rfl\n  | cj a b iha ihb =>\n    simp only [val]\n    revert iha ihb\n    cases val P Q a <;> cases val P Q b <;> cases val P' Q' a <;> cases val P' Q' b <;> simp [omin]\n  | dj a b iha ihb =>\n    simp only [val]\n    revert iha ihb\n    cases val P Q a <;> cases val P Q b <;> cases val P' Q' a <;> cases val P' Q' b <;> simp [omax]\n  | box a ih =>\n    simp only [val]; revert ih\n    cases val P Q a <;> cases val P' Q' a <;> simp [osucc]\n\ntheorem val_fin (m n : Nat) : ∀ a, negFree a = true → (val (some m) (some n) a).isSome = true := by\n  intro a\n  induction a with\n  | bot => intro _; rfl\n  | pa => intro _; rfl\n  | qa => intro _; rfl\n  | neg a _ => intro hn; simp [negFree] at hn\n  | cj a b iha ihb =>\n    intro hn; simp only [negFree, Bool.and_eq_true] at hn\n    have ha := iha hn.1; have hb := ihb hn.2\n    simp only [val]; revert ha hb\n    cases val (some m) (some n) a <;> cases val (some m) (some n) b <;> simp [omin]\n  | dj a b iha ihb =>\n    intro hn; simp only [negFree, Bool.and_eq_true] at hn\n    have ha := iha hn.1; have hb := ihb hn.2\n    simp only [val]; revert ha hb\n    cases val (some m) (some n) a <;> cases val (some m) (some n) b <;> simp [omax]\n  | box a ih =>\n    intro hn; simp only [negFree] at hn\n    have ha := ih hn; simp only [val]; revert ha\n    cases val (some m) (some n) a <;> simp [osucc]\n\ntheorem all_tt (v : Option Nat) : (∀ h, TT v h) ↔ v = none := by\n  cases v with\n  | none => simp [TT]\n  | some n => simp only [TT]; constructor\n              · intro H; have := H n; omega\n              · intro H; cases H\n\ntheorem eventually_false (v : Option Nat) (hv : v.isSome = true) : ∃ H, ∀ h, H ≤ h → ¬ TT v h := by\n  cases v with\n  | none => simp at hv\n  | some n => exact ⟨n, fun h hh => by simp only [TT]; omega⟩\n\n/-- A negation-free guarded opponent gets the same outcome against every graded FairBot F_j, F_j'. -/\ntheorem negfree_same (O : Fm) (hg : Guarded O) (hn : negFree O = true) (j j' : Nat)\n    (o f o' f' : Nat → Prop) (G : GameRec O j o f) (G' : GameRec O j' o' f') : SameOut o f o' f' := by\n  classical\n  have hA : ∀ i x, (A O i x ↔ TT (val none (some i) O) x) := fun i x => by\n    unfold A; rw [evA]; exact val_ev _ _ O hn x\n  have hall : ∀ i, ((∀ x, A O i x) ↔ val none (some i) O = none) := fun i => by\n    rw [← all_tt]; exact ⟨fun H x => (hA i x).1 (H x), fun H x => (hA i x).2 (H x)⟩\n  have indep : (val none (some j) O = none) ↔ (val none (some j') O = none) := by\n    have := val_none none (some j) none (some j') rfl rfl O\n    rw [← Option.isNone_iff_eq_none, ← Option.isNone_iff_eq_none, this]\n  by_cases hc : ∀ x, A O j x\n  · left\n    have hc' : ∀ x, A O j' x := (hall j').2 (indep.1 ((hall j).1 hc))\n    exact ⟨all_coop hg G hc, all_coop hg G' hc'⟩\n  · right\n    have hc' : ¬ ∀ x, A O j' x := fun h => hc ((hall j).2 (indep.2 ((hall j').1 h)))\n    have ex : ∃ x, ¬ A O j x := Classical.byContradiction (fun hn' => hc (fun x => Classical.byContradiction (fun hx => hn' ⟨x, hx⟩)))\n    have ex' : ∃ x, ¬ A O j' x := Classical.byContradiction (fun hn' => hc' (fun x => Classical.byContradiction (fun hx => hn' ⟨x, hx⟩)))\n    obtain ⟨x0, hx0⟩ := ex\n    obtain ⟨x1, hx1⟩ := ex'\n    obtain ⟨g0, s0, m0⟩ := least x0 hx0\n    obtain ⟨g1, s1, m1⟩ := least x1 hx1\n    obtain ⟨hf, ho⟩ := tail_form hg G g0 s0 m0\n    obtain ⟨hf', ho'⟩ := tail_form hg G' g1 s1 m1\n    obtain ⟨H0, e0⟩ := eventually_false _ (val_fin (g0 + j) j O hn)\n    obtain ⟨H1, e1⟩ := eventually_false _ (val_fin (g1 + j') j' O hn)\n    refine ⟨H0 + H1 + g0 + g1 + j + j', fun h hh => ⟨?_, ?_, ?_⟩⟩\n    · rw [ho h, ho' h, evT, evT, val_ev _ _ O hn h, val_ev _ _ O hn h]\n      exact ⟨fun x => absurd x (e0 h (by omega)), fun x => absurd x (e1 h (by omega))⟩\n    · rw [hf h]; omega\n    · rw [hf' h]; omega\n\n/-! Binary-free (unary) formulas: traces stay in {threshold, co-threshold} -/\ndef UT (b : Bool) (v : Option Nat) (h : Nat) : Prop := if b then ¬ TT v h else TT v h\n\ndef bx : Bool × Option Nat → Bool × Option Nat\n  | (false, v) => (false, osucc v)\n  | (true, none) => (false, some 1)\n  | (true, some 0) => (false, none)\n  | (true, some (_ + 1)) => (false, some 1)\n\ndef uval (P Q : Option Nat) : Fm → Bool × Option Nat\n  | bot => (false, some 0) | pa => (false, P) | qa => (false, Q)\n  | neg a => (!(uval P Q a).1, (uval P Q a).2)\n  | cj _ _ => (false, none)\n  | dj _ _ => (false, none)\n  | box a => bx (uval P Q a)\n\ntheorem bx_ev (x : Bool × Option Nat) (h : Nat) :\n    ((∀ g, g < h → UT x.1 x.2 g) ↔ UT (bx x).1 (bx x).2 h) := by\n  obtain ⟨b, v⟩ := x\n  cases b with\n  | false => simp only [UT, bx]; exact tt_box v h\n  | true =>\n    rcases v with _ | _ | n\n    · simp [UT, bx, TT]\n      constructor\n      · intro H; have := H 0; omega\n      · intro hh g; omega\n    · simp [UT, bx, TT]\n    · simp [UT, bx, TT]\n      constructor\n      · intro H; apply Classical.byContradiction; intro hn; have := H 0 (by omega); omega\n      · intro hh g hg; omega\n\ntheorem uval_ev (P Q : Option Nat) : ∀ (a : Fm), noBin a = true → ∀ h,\n    (ev (TT P) (TT Q) a h ↔ UT (uval P Q a).1 (uval P Q a).2 h) := by\n  intro a\n  induction a with\n  | bot => intro _ h; simp [ev, uval, UT, TT]\n  | pa => intro _ h; simp [ev, uval, UT]\n  | qa => intro _ h; simp [ev, uval, UT]\n  | neg a ih =>\n    intro hn h; simp only [noBin] at hn\n    simp only [ev, uval]; rw [ih hn h]\n    cases (uval P Q a).1 <;> simp [UT]\n  | cj a b _ _ => intro hn; simp [noBin] at hn\n  | dj a b _ _ => intro hn; simp [noBin] at hn\n  | box a ih =>\n    intro hn h; simp only [noBin] at hn\n    simp only [ev, uval]; rw [← bx_ev]\n    exact ⟨fun H g hg => (ih hn g).1 (H g hg), fun H g hg => (ih hn g).2 (H g hg)⟩\n\n/-- class of a threshold: infinite / zero / positive -/\ndef cls : Option Nat → Nat\n  | none => 0\n  | some 0 => 1\n  | some (_ + 1) => 2\n\ndef ucls (x : Bool × Option Nat) : Bool × Nat := (x.1, cls x.2)\n\ntheorem bx_cls (x y : Bool × Option Nat) (h : ucls x = ucls y) : ucls (bx x) = ucls (bx y) := by\n  obtain ⟨b, v⟩ := x; obtain ⟨c, w⟩ := y\n  cases b <;> cases c <;> rcases v with _ | _ | v <;> rcases w with _ | _ | w <;> simp_all [ucls, cls, bx, osucc]\n\ntheorem uval_cls (P Q P' Q' : Option Nat) (hP : cls P = cls P') (hQ : cls Q = cls Q') :\n    ∀ a, ucls (uval P Q a) = ucls (uval P' Q' a) := by\n  intro a\n  induction a with\n  | bot => rfl\n  | pa => simp [uval, ucls, hP]\n  | qa => simp [uval, ucls, hQ]\n  | neg a ih => simp only [ucls, uval] at ih ⊢; simp_all\n  | cj a b _ _ => rfl\n  | dj a b _ _ => rfl\n  | box a ih => simp only [uval]; exact bx_cls _ _ ih\n\n/-- whether a (co)threshold trace is true at all heights, and its eventual value -/\ndef allv (x : Bool × Nat) : Bool := (x.1 = false ∧ x.2 = 0) ∨ (x.1 = true ∧ x.2 = 1)\ndef tlv (x : Bool × Nat) : Bool := (x.1 = false ∧ x.2 = 0) ∨ (x.1 = true ∧ x.2 ≠ 0)\n\ntheorem allv_iff (x : Bool × Option Nat) : (∀ h, UT x.1 x.2 h) ↔ allv (ucls x) = true := by\n  obtain ⟨b, v⟩ := x\n  cases b <;> rcases v with _ | _ | v <;> simp [UT, TT, allv, ucls, cls]\n  · exact ⟨v+1, by omega⟩\n  · exact ⟨0, by omega⟩\n\ntheorem tlv_ev (x : Bool × Option Nat) : ∃ H, ∀ h, H ≤ h → (UT x.1 x.2 h ↔ tlv (ucls x) = true) := by\n  obtain ⟨b, v⟩ := x\n  refine ⟨(match v with | none => 0 | some n => n), fun h hh => ?_⟩\n  cases b <;> rcases v with _ | _ | v <;> simp [UT, TT, tlv, ucls, cls] at hh ⊢ <;> omega\n\ntheorem cls_pos (n : Nat) (hn : 1 ≤ n) : cls (some n) = 2 := by\n  cases n with\n  | zero => omega\n  | succ n => rfl\n\n/-- A binary-free guarded opponent gets the same outcome against every F_j, F_j' with j, j' ≥ 1. -/\ntheorem nobin_same (O : Fm) (hg : Guarded O) (hn : noBin O = true) (j j' : Nat) (hj : 1 ≤ j) (hj' : 1 ≤ j')\n    (o f o' f' : Nat → Prop) (G : GameRec O j o f) (G' : GameRec O j' o' f') : SameOut o f o' f' := by\n  classical\n  have hA : ∀ i x, (A O i x ↔ UT (uval none (some i) O).1 (uval none (some i) O).2 x) := fun i x => by\n    unfold A; rw [evA]; exact uval_ev _ _ O hn x\n  have hall : ∀ i, ((∀ x, A O i x) ↔ allv (ucls (uval none (some i) O)) = true) := fun i => by\n    rw [← allv_iff]; exact ⟨fun H x => (hA i x).1 (H x), fun H x => (hA i x).2 (H x)⟩\n  have same := uval_cls none (some j) none (some j') rfl (by rw [cls_pos j hj, cls_pos j' hj']) O\n  by_cases hc : ∀ x, A O j x\n  · left\n    have hc' : ∀ x, A O j' x := (hall j').2 (same ▸ (hall j).1 hc)\n    exact ⟨all_coop hg G hc, all_coop hg G' hc'⟩\n  · right\n    have hc' : ¬ ∀ x, A O j' x := fun h => hc ((hall j).2 (same ▸ (hall j').1 h))\n    have ex : ∃ x, ¬ A O j x := Classical.byContradiction (fun hn' => hc (fun x => Classical.byContradiction (fun hx => hn' ⟨x, hx⟩)))\n    have ex' : ∃ x, ¬ A O j' x := Classical.byContradiction (fun hn' => hc' (fun x => Classical.byContradiction (fun hx => hn' ⟨x, hx⟩)))\n    obtain ⟨x0, hx0⟩ := ex\n    obtain ⟨x1, hx1⟩ := ex'\n    obtain ⟨g0, s0, m0⟩ := least x0 hx0\n    obtain ⟨g1, s1, m1⟩ := least x1 hx1\n    obtain ⟨hf, ho⟩ := tail_form hg G g0 s0 m0\n    obtain ⟨hf', ho'⟩ := tail_form hg G' g1 s1 m1\n    have tsame := uval_cls (some (g0 + j)) (some j) (some (g1 + j')) (some j')\n      (by rw [cls_pos _ (by omega), cls_pos _ (by omega)]) (by rw [cls_pos j hj, cls_pos j' hj']) O\n    obtain ⟨H0, e0⟩ := tlv_ev (uval (some (g0 + j)) (some j) O)\n    obtain ⟨H1, e1⟩ := tlv_ev (uval (some (g1 + j')) (some j') O)\n    refine ⟨H0 + H1 + g0 + g1 + j + j', fun h hh => ⟨?_, ?_, ?_⟩⟩\n    · rw [ho h, ho' h, evT, evT, uval_ev _ _ O hn h, uval_ev _ _ O hn h, e0 h (by omega), e1 h (by omega), tsame]\n    · rw [hf h]; omega\n    · rw [hf' h]; omega\n\n/-! Counting: non-box nodes and box nodes -/\ndef nb : Fm → Nat\n  | bot => 1 | pa => 1 | qa => 1\n  | neg a => nb a + 1\n  | cj a b => nb a + nb b + 1\n  | dj a b => nb a + nb b + 1\n  | box a => nb a\n\ndef nbox : Fm → Nat\n  | bot => 0 | pa => 0 | qa => 0\n  | neg a => nbox a\n  | cj a b => nbox a + nbox b\n  | dj a b => nbox a + nbox b\n  | box a => nbox a + 1\n\ntheorem size_split (a : Fm) : size a = nb a + nbox a := by\n  induction a <;> simp only [size, nb, nbox] <;> omega\n\ntheorem md_le_nbox (a : Fm) : md a ≤ nbox a := by\n  induction a <;> simp only [md, nbox] <;> omega\n\ntheorem nb_pos (a : Fm) : 1 ≤ nb a := by\n  induction a <;> simp only [nb] <;> omega\n\ntheorem nb_neg (a : Fm) (h : negFree a = false) : 2 ≤ nb a := by\n  induction a with\n  | bot => simp [negFree] at h\n  | pa => simp [negFree] at h\n  | qa => simp [negFree] at h\n  | neg a _ => have := nb_pos a; simp only [nb]; omega\n  | cj a b iha ihb =>\n    simp only [negFree, Bool.and_eq_false_iff] at h; simp only [nb]\n    rcases h with h | h\n    · have := iha h; have := nb_pos b; omega\n    · have := ihb h; have := nb_pos a; omega\n  | dj a b iha ihb =>\n    simp only [negFree, Bool.and_eq_false_iff] at h; simp only [nb]\n    rcases h with h | h\n    · have := iha h; have := nb_pos b; omega\n    · have := ihb h; have := nb_pos a; omega\n  | box a ih => simp only [negFree] at h; simp only [nb]; exact ih h\n\ntheorem nb_bin (a : Fm) (h : noBin a = false) : 3 ≤ nb a := by\n  induction a with\n  | bot => simp [noBin] at h\n  | pa => simp [noBin] at h\n  | qa => simp [noBin] at h\n  | neg a ih => simp only [noBin] at h; simp only [nb]; have := ih h; omega\n  | cj a b _ _ => have := nb_pos a; have := nb_pos b; simp only [nb]; omega\n  | dj a b _ _ => have := nb_pos a; have := nb_pos b; simp only [nb]; omega\n  | box a ih => simp only [noBin] at h; simp only [nb]; exact ih h\n\ntheorem nb_both (a : Fm) (h1 : negFree a = false) (h2 : noBin a = false) : 4 ≤ nb a := by\n  induction a with\n  | bot => simp [noBin] at h2\n  | pa => simp [noBin] at h2\n  | qa => simp [noBin] at h2\n  | neg a _ => simp only [noBin] at h2; simp only [nb]; have := nb_bin a h2; omega\n  | cj a b _ _ =>\n    simp only [negFree, Bool.and_eq_false_iff] at h1; simp only [nb]\n    rcases h1 with h | h\n    · have := nb_neg a h; have := nb_pos b; omega\n    · have := nb_neg b h; have := nb_pos a; omega\n  | dj a b _ _ =>\n    simp only [negFree, Bool.and_eq_false_iff] at h1; simp only [nb]\n    rcases h1 with h | h\n    · have := nb_neg a h; have := nb_pos b; omega\n    · have := nb_neg b h; have := nb_pos a; omega\n  | box a ih => simp only [negFree] at h1; simp only [noBin] at h2; simp only [nb]; exact ih h1 h2\n\n/-- MAIN: for every k ≥ 1, every guarded separator of F_k and F_{k+1} has a negation, a binary\n connective and modal depth ≥ k+1, hence AST size ≥ k+5 (attained by S_k, K49). -/\ntheorem size_bound (O : Fm) (k : Nat) (hk : 1 ≤ k) (hg : Guarded O)\n    (o f o' f' : Nat → Prop) (G : GameRec O k o f) (G' : GameRec O (k+1) o' f')\n    (hsep : ¬ SameOut o f o' f') :\n    negFree O = false ∧ noBin O = false ∧ k + 1 ≤ md O ∧ k + 5 ≤ size O := by\n  have h1 : negFree O = false := by\n    cases hb : negFree O\n    · rfl\n    · exact absurd (negfree_same O hg hb k (k+1) o f o' f' G G') hsep\n  have h2 : noBin O = false := by\n    cases hb : noBin O\n    · rfl\n    · exact absurd (nobin_same O hg hb k (k+1) hk (by omega) o f o' f' G G') hsep\n  have h3 : k + 1 ≤ md O := by\n    apply Classical.byContradiction; intro hn\n    exact hsep (same_outcome O k hg (by omega) o f o' f' G G')\n  have := nb_both O h1 h2\n  have := md_le_nbox O\n  have := size_split O\n  exact ⟨h1, h2, h3, by omega⟩\n\ntheorem sk_size (k : Nat) : size (box (dj (neg qa) (boxes k bot))) = k + 5 := by\n  have : ∀ n, size (boxes n bot) = n + 1 := by\n    intro n; induction n with\n    | zero => rfl\n    | succ n ih => simp [boxes, size, ih]\n  simp [size, this]; omega\n\n#print axioms negfree_same\n#print axioms nobin_same\n#print axioms size_bound\n#print axioms sk_size\n"
LEANSHA = '403107ee2530853e08d8571d8280415749b2c6c6a3a67592f65c8b1aca9cf839'
import subprocess, shutil, os, hashlib, sys, time
t0 = time.time()
assert hashlib.sha256(LEAN.encode()).hexdigest() == LEANSHA
binary = next((p for p in (shutil.which('lean'), '/opt/elan/bin/lean', os.path.expanduser('~/.elan/bin/lean')) if p and os.path.exists(p)), None)
assert binary, 'lean missing'
def run(src): return subprocess.run([binary, '--stdin'], input=src, text=True, capture_output=True, timeout=110)

# ---- Part 2 first (cheap) : literal evaluator ----
def size(f):
    t = f[0]
    if t in ('F', 'p', 'q'): return 1
    if t in ('~', 'B'): return 1 + size(f[1])
    return 1 + size(f[1]) + size(f[2])
def guarded(f):
    t = f[0]
    if t == 'F': return True
    if t in ('p', 'q'): return False
    if t == 'B': return True
    if t == '~': return guarded(f[1])
    return guarded(f[1]) and guarded(f[2])
def negfree(f):
    t = f[0]
    if t in ('F', 'p', 'q'): return True
    if t == '~': return False
    if t == 'B': return negfree(f[1])
    return negfree(f[1]) and negfree(f[2])
def nobin(f):
    t = f[0]
    if t in ('F', 'p', 'q'): return True
    if t in ('~', 'B'): return nobin(f[1])
    return False
def nboxes(f):
    t = f[0]
    if t in ('F', 'p', 'q'): return 0
    if t == '~': return nboxes(f[1])
    if t == 'B': return 1 + nboxes(f[1])
    return nboxes(f[1]) + nboxes(f[2])

def subs(f, acc):
    if f in acc: return
    for c in f[1:]: subs(c, acc)
    acc[f] = len(acc)

def game(O, j):
    """O vs F_j: returns (o tail, f tail, all-coop) using the K40 horizon 2(b(O)+j)+4"""
    H = 2 * (nboxes(O) + j) + 4
    acc = {}; subs(O, acc); order = list(acc)
    tr = {s: [] for s in order}; allt = {s: True for s in order}  # allt: conj of child trace so far (for boxes)
    pref = {s: True for s in order}
    o = []; f = []
    for h in range(H + 1):
        fh = all(o[g] for g in range(0, h - j + 1))
        pval, qval = fh, h < j
        for s in order:
            t = s[0]
            if t == 'F': v = False
            elif t == 'p': v = pval
            elif t == 'q': v = qval
            elif t == '~': v = not tr[s[1]][h]
            elif t == '&': v = tr[s[1]][h] and tr[s[2]][h]
            elif t == '|': v = tr[s[1]][h] or tr[s[2]][h]
            else: v = all(tr[s[1]][:h])
            tr[s].append(v)
        # p at h depends on o at g <= h-j < h: consistent since j >= 1
        o.append(tr[O][h]); f.append(fh)
    allc = all(o) and all(f)
    return (allc, o[-1], f[-1])

def outcome(O, j):
    allc, ot, ft = game(O, j)
    return 'CC' if allc else (('C' if ot else 'D') + ('C' if ft else 'D'))

def enum(N):
    by = {1: [('F',), ('p',), ('q',)]}
    for n in range(2, N + 1):
        L = []
        for a in by[n - 1]: L.append(('~', a)); L.append(('B', a))
        for i in range(1, n - 1):
            for a in by[i]:
                for b in by[n - 1 - i]:
                    if i < n - 1 - i or (i == n - 1 - i and a <= b):
                        L.append(('&', a, b)); L.append(('|', a, b))
        by[n] = L
    return by

by = enum(9)
nn = 0; nseps = 0
for n in range(1, 10):
    for O in by[n]:
        if not guarded(O): continue
        if n <= 8 and (negfree(O) or nobin(O)):
            outs = {outcome(O, j) for j in range(1, 6)}
            assert all(x in ('CC', 'DD', 'CD', 'DC') for x in outs)
            # same outcome in the sense of SameOut: CC everywhere, or same eventual pair with both F defecting
            assert len(outs) == 1, (O, outs)
            nn += 1
        for k in range(1, 5):
            if outcome(O, k) != outcome(O, k + 1):
                nseps += 1
                assert not negfree(O) and not nobin(O), O
                assert n >= k + 5, (O, k)
assert nn > 3000, nn
assert nseps > 0
print('literal: %d negation-free/binary-free guarded formulas (size<=8) same vs F_1..F_5; %d separator cells (size<=9, k<=4) all with ~ and binary, size>=k+5' % (nn, nseps))
SK = lambda k: ('B', ('|', ('~', ('q',)), (lambda f: f)(nest(k))))
def nest(k):
    f = ('F',)
    for _ in range(k): f = ('B', f)
    return f
for k in range(1, 7):
    S = SK(k); assert size(S) == k + 5 and outcome(S, k) == 'CC' and outcome(S, k + 1) == 'DD'
print('S_k size k+5, CC vs F_k, DD vs F_{k+1}, k<=6')

# ---- Part 1: Lean ----
r = run(LEAN)
out = r.stdout + r.stderr
assert r.returncode == 0, out
for thm in ('negfree_same', 'nobin_same', 'size_bound', 'sk_size'):
    line = [l for l in out.splitlines() if l.startswith("'%s' depends on axioms" % thm)]
    assert len(line) == 1, (thm, out)
    assert 'sorryAx' not in line[0] and 'ofReduceBool' not in line[0], line[0]
print('Lean: negfree_same, nobin_same, size_bound, sk_size proved (no sorryAx)')
MUT = [
    ('k + 1 ≤ md O ∧ k + 5 ≤ size O := by', 'k + 1 ≤ md O ∧ k + 6 ≤ size O := by'),
    ('  | (true, some 0) => (false, none)\n', '  | (true, some 0) => (false, some 1)\n'),
    ('  | some 0 => 1\n', '  | some 0 => 2\n'),
    ('theorem nb_both (a : Fm) (h1 : negFree a = false) (h2 : noBin a = false) : 4 ≤ nb a', 'theorem nb_both (a : Fm) (h1 : negFree a = false) (h2 : noBin a = false) : 5 ≤ nb a'),
]
for a, b in MUT:
    assert LEAN.count(a) == 1, a
    r = run(LEAN.replace(a, b))
    assert r.returncode != 0 or 'sorryAx' in r.stdout, ('mutation accepted', a)
print('4 mutations rejected')
